import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner sc=new Scanner(System.in);
		int t=sc.nextInt();
		while(t-->0){
		    int n=sc.nextInt();
		    int m=n*3;
		    long[]arr=new long[m];
		    for(int i=0;i<m;i++){
		        arr[i]=sc.nextLong();
		    }
		    Arrays.sort(arr);
		    long[] pre=new long[m+1];
		    for(int i=0;i<m;i++){
		        pre[i+1]=pre[i]+arr[i];
		    }
		    long ans=0;
		    for(int x=0;x<=n;x++){
		        int low=0;
		        int high=n-x;
		        while(low<high){
		            int b=(low+high)/2;
		            int a=x+2*b;
		            int k=3*n-2*x-b;
		            long diff=(pre[m-a]-pre[m-a-2])-3*(pre[m-k+1]-pre[m-k]);
		            if(diff>=0){
		                low=b+1;
		            }
		            else{
		                high=b;
		            }
		        }
		        for(int b=Math.max(0,low-1);b<=Math.min(n-x,low);b++){
		            int a=x+2*b;
		            int k=3*n-2*x-b;
		            long sum=3*(pre[m]-pre[m-k])+2*(pre[m]-pre[m-x])+(pre[m]-pre[m-a]);
		            ans=Math.max(ans,sum);
		        }
		    }
		    System.out.println(ans);
		    
		}
		sc.close();

	}
}
